style.css:
@-moz-document url-prefix("https://github.com/users/AquilaLeiteMendes/projects/") {
/* ========================================================
       01. DESIGN TOKENS
       ======================================================== */

    :root {
        --gcu-column-min: 320px;
        --gcu-column-max: 420px;

        --gcu-card-padding: 10px 12px;
        --gcu-card-radius: 8px;
        --gcu-card-gap: 8px;

        --gcu-heading-weight: 650;
        --gcu-title-size: 14px;
        --gcu-title-line-height: 1.4;

        --gcu-board-padding: 8px;
    }


    /* ========================================================
       02. LAYOUT PRINCIPAL
       ======================================================== */

    /*
     * Evita limitações de largura em contêineres conhecidos.
     * Não remove barras laterais.
     */

    .application-main {
        max-width: 100% !important;
        min-width: 0;
    }

    main {
        min-width: 0;
    }


    /* ========================================================
       03. BOARD / KANBAN
       ======================================================== */

    /*
     * Ajuste de espaçamento somente em elementos
     * identificados como contêineres de Board.
     */

    [data-testid*="board-view"],
    [data-testid="project-view-root"] {
        min-width: 0;
    }

    /*
     * Colunas: seletores condicionais.
     * Confirmar os nomes no DOM antes de utilizar.
     */

    [data-testid*="board-column"],
    [class*="BoardColumn"],
    [class*="board-column"] {
        min-width: var(--gcu-column-min) !important;
        max-width: var(--gcu-column-max) !important;
    }

    /*
     * Cabeçalhos das colunas.
     */

    [class*="ColumnHeader"],
    [class*="column-header"] {
        font-weight: var(--gcu-heading-weight) !important;
    }


    /* ========================================================
       04. CARDS
       ======================================================== */

    /*
     * Cartões de tarefas.
     */

    [data-testid*="board-card"],
    [class*="BoardCard"],
    [class*="board-card"] {
        padding: var(--gcu-card-padding) !important;
        border-radius: var(--gcu-card-radius) !important;
        margin-bottom: var(--gcu-card-gap) !important;
        overflow-wrap: anywhere;
    }

    /*
     * Títulos dos cartões.
     */

    [data-testid*="board-card"] a,
    [class*="BoardCard"] a,
    [class*="board-card"] a {
        font-size: var(--gcu-title-size) !important;
        line-height: var(--gcu-title-line-height) !important;
        font-weight: 600 !important;
    }


    /* ========================================================
       05. TIPOGRAFIA
       ======================================================== */

    .Link--primary {
        font-weight: 600 !important;
    }

    /*
     * Não altera globalmente o tamanho de fontes,
     * evitando interferência em menus e controles.
     */


    /* ========================================================
       06. ACESSIBILIDADE
       ======================================================== */

    a:focus-visible,
    button:focus-visible,
    input:focus-visible,
    [tabindex]:focus-visible {
        outline: 2px solid var(--fgColor-accent, #0969da);
        outline-offset: 2px;
    }


    /* ========================================================
       07. RESPONSIVIDADE
       ======================================================== */

    @media (max-width: 768px) {

        :root {
            --gcu-column-min: 280px;
            --gcu-column-max: 340px;
            --gcu-card-padding: 9px;
        }

    }


    /* ========================================================
       08. TEMAS
       ======================================================== */

    /*
     * Não define cores de fundo ou texto.
     * Preserva os temas claro e escuro do GitHub.
     */
}
